import java.util.Scanner;
public class JTemperatureAboveAverage {
	public static void main(String[] args) {
		//Khutwa 1: Iqra adad al-ayam allati yajib idkhal bayanat darajat al-harara laha.
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adad qiyam darajat al-harara allati sayutim idkhaluha:");
		int numDays = scan.nextInt();
		//Khutwa 2: Iqra qiyam al-harara wa'uhdith al-majmu' al-jari
		double[] temps = new double[numDays];
		int total = 0;
		for (int i = 0; i < numDays; i++) {
			System.out.println("Adkhil darajat al-harara: " );
			temps[i] = scan.nextDouble();
			total += temps[i];
		}
		scan.close();
		//Khutwa 3: Ihsib al-mutawassit li darajat al-harara
		double average = 0;
		if (numDays == 0) {
			System.out.println("Lam tudkhal ay qiyam darajat al-harara.");
		} else {
			average = (double) total / numDays;			
		}
		//Khutwa 4: A'adad al-ayam allati takun fiha al-daraja a'la min al-mutawassit
		int above = 0;
		for (double x : temps) {
			if (x > average) {
				above++;
			}
		}
		//Khutwa 5: 'Arid al-nata'ij
		System.out.println("al-mutawassit = " + average);
		System.out.println(above + " ayam a'la min al-mutawassit.");
	}
}
